package com.example.blog.shared.seguranca;

import jakarta.servlet.http.HttpServletRequest;

import org.springframework.http.HttpHeaders;
import org.springframework.security.oauth2.server.resource.InvalidBearerTokenException;
import org.springframework.security.oauth2.server.resource.web.BearerTokenResolver;

/**
 * Lê o token do cabeçalho {@code Authorization: Token <jwt>}, exigido pelo contrato da API.
 * Cabeçalho ausente significa requisição anônima; qualquer outro formato é token inválido.
 */
public class TokenHeaderResolver implements BearerTokenResolver {

    private static final String PREFIXO = "Token ";

    @Override
    public String resolve(HttpServletRequest request) {
        String cabecalho = request.getHeader(HttpHeaders.AUTHORIZATION);
        if (cabecalho == null) {
            return null;
        }
        if (!cabecalho.startsWith(PREFIXO)) {
            throw new InvalidBearerTokenException("Cabeçalho Authorization fora do formato 'Token <jwt>'");
        }
        String token = cabecalho.substring(PREFIXO.length()).strip();
        if (token.isEmpty()) {
            throw new InvalidBearerTokenException("Cabeçalho Authorization sem token");
        }
        return token;
    }
}

