import org.springframework.security.web.AuthenticationEntryPoint;

import com.example.blog.shared.erro.ErroResponse;

import tools.jackson.databind.json.JsonMapper;

/** Responde 401 no formato de erro do contrato, distinguindo token ausente de token inválido. */
public class ErroAutenticacaoEntryPoint implements AuthenticationEntryPoint {

    private static final String CONTENT_TYPE_JSON_UTF8 = MediaType.APPLICATION_JSON_VALUE + ";charset=UTF-8";

    private final JsonMapper jsonMapper;

    public ErroAutenticacaoEntryPoint(JsonMapper jsonMapper) {
        this.jsonMapper = jsonMapper;
    }

    @Override
    public void commence(HttpServletRequest request, HttpServletResponse response,
            AuthenticationException excecao) throws IOException {
        String mensagem = request.getHeader(HttpHeaders.AUTHORIZATION) == null ? "is missing" : "is invalid";
        response.setStatus(HttpStatus.UNAUTHORIZED.value());
        response.setContentType(CONTENT_TYPE_JSON_UTF8);
        response.getWriter().write(jsonMapper.writeValueAsString(ErroResponse.de("token", mensagem)));
    }
}

