                .exceptionHandling(excecoes -> excecoes.authenticationEntryPoint(entryPoint));
        return http.build();
    }

    static SecretKey chave(JwtProperties propriedades) {
        return new SecretKeySpec(propriedades.segredoEmBytes(), ALGORITMO_HMAC);
    }
}

