import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.temporal.ChronoUnit;

import org.junit.jupiter.api.Test;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.oauth2.jwt.JwtDecoder;
import org.springframework.security.oauth2.jwt.JwtException;

import com.example.blog.shared.erro.TokenInvalidoException;

class TokenServiceTest {

    private static final String SEGREDO = "segredo-ficticio-de-teste-com-mais-de-32-bytes";
    private static final String OUTRO_SEGREDO = "outro-segredo-ficticio-de-teste-com-32-bytes-ou-mais";
    private static final JwtProperties PROPRIEDADES = new JwtProperties(SEGREDO, Duration.ofHours(24), "conduit");

    private final SegurancaConfig config = new SegurancaConfig();
    private final JwtDecoder decoder = config.jwtDecoder(PROPRIEDADES);

    @Test
    void deveEmitirTokenQueDecodificaComSubjectEExpiracaoDe24Horas() {
        Instant agora = Instant.now().truncatedTo(ChronoUnit.SECONDS);
        TokenService service = servico(PROPRIEDADES, Clock.fixed(agora, ZoneOffset.UTC));

        Jwt jwt = decoder.decode(service.emitir(42L));

        assertThat(jwt.getSubject()).isEqualTo("42");
        assertThat(jwt.getIssuedAt()).isEqualTo(agora);
        assertThat(jwt.getExpiresAt()).isEqualTo(agora.plus(Duration.ofHours(24)));
        assertThat(service.idDoUsuario(jwt)).isEqualTo(42L);
    }

    @Test
    void deveRejeitarTokenExpirado() {
        Instant duasHorasAtras = Instant.now().minus(Duration.ofHours(2));
        JwtProperties validadeCurta = new JwtProperties(SEGREDO, Duration.ofHours(1), "conduit");
        String token = servico(validadeCurta, Clock.fixed(duasHorasAtras, ZoneOffset.UTC)).emitir(1L);

        assertThatThrownBy(() -> decoder.decode(token)).isInstanceOf(JwtException.class);
    }

    @Test
    void deveRejeitarTokenAssinadoComOutraChave() {
        JwtProperties outraChave = new JwtProperties(OUTRO_SEGREDO, Duration.ofHours(24), "conduit");
        String token = servico(outraChave, Clock.systemUTC()).emitir(1L);

        assertThatThrownBy(() -> decoder.decode(token)).isInstanceOf(JwtException.class);
    }

    @Test
    void deveRejeitarTokenDeOutroEmissor() {
        JwtProperties outroEmissor = new JwtProperties(SEGREDO, Duration.ofHours(24), "outro");
        String token = servico(outroEmissor, Clock.systemUTC()).emitir(1L);

        assertThatThrownBy(() -> decoder.decode(token)).isInstanceOf(JwtException.class);
    }

    @Test
    void deveLancarTokenInvalidoQuandoSubjectNaoENumerico() {
        Jwt jwt = Jwt.withTokenValue("x").header("alg", "HS256").subject("abc").build();

        assertThatThrownBy(() -> servico(PROPRIEDADES, Clock.systemUTC()).idDoUsuario(jwt))
                .isInstanceOf(TokenInvalidoException.class);
    }

    @Test
    void deveRecusarSegredoComMenosDe32Bytes() {
        assertThatThrownBy(() -> new JwtProperties("curto", Duration.ofHours(1), "conduit"))
                .isInstanceOf(IllegalArgumentException.class);
    }

    private TokenService servico(JwtProperties propriedades, Clock clock) {
        return new TokenService(config.jwtEncoder(propriedades), propriedades, clock);
    }
}

