package com.example.blog.usuario.service;

/**
 * Alteração parcial do usuário atual. Cada campo diz se foi enviado e com qual valor, o que permite
 * distinguir "campo ausente" (mantém o valor) de "campo enviado como null" (apaga {@code bio}/{@code image}).
 */
public record AlteracaoUsuario(Campo email, Campo username, Campo password, Campo bio, Campo image) {

    /** Campo de uma alteração parcial; {@code valor} só tem significado quando {@code presente} é verdadeiro. */
    public record Campo(boolean presente, String valor) {

        public static final Campo AUSENTE = new Campo(false, null);

        public static Campo com(String valor) {
            return new Campo(true, valor);
        }
    }

    public AlteracaoUsuario {
        email = email == null ? Campo.AUSENTE : email;
        username = username == null ? Campo.AUSENTE : username;
        password = password == null ? Campo.AUSENTE : password;
        bio = bio == null ? Campo.AUSENTE : bio;
        image = image == null ? Campo.AUSENTE : image;
    }

    /** Indica que nenhum campo aceito foi enviado. */
    public boolean isVazia() {
        return !email.presente() && !username.presente() && !password.presente()
                && !bio.presente() && !image.presente();
    }
}

