package com.example.blog.usuario.web;

import jakarta.validation.Validator;
import jakarta.validation.constraints.Email;

import org.springframework.stereotype.Component;

import com.example.blog.shared.erro.ValidacaoException;
import com.example.blog.usuario.service.AlteracaoUsuario;
import com.example.blog.usuario.service.AlteracaoUsuario.Campo;

import tools.jackson.databind.JsonNode;

/**
 * Converte o corpo de {@code PUT /api/user} em {@link AlteracaoUsuario}, aplicando as regras de formato.
 * O corpo chega como {@link JsonNode} para distinguir campo ausente de campo enviado como {@code null}.
 */
@Component
public class AlteracaoUsuarioMapper {

    private static final String RAIZ = "user";
    private static final String NAO_PODE_SER_VAZIO = "can't be blank";
    private static final String INVALIDO = "is invalid";

    private final Validator validator;

    public AlteracaoUsuarioMapper(Validator validator) {
        this.validator = validator;
    }

    /**
     * @throws ValidacaoException se faltar o objeto {@code user}, se ele não tiver nenhum campo aceito
     *     ou se algum campo violar as regras de formato
     */
    public AlteracaoUsuario converter(JsonNode corpo) {
        JsonNode user = corpo == null ? null : corpo.get(RAIZ);
        if (user == null || user.isNull()) {
            throw new ValidacaoException(RAIZ, NAO_PODE_SER_VAZIO);
        }
        if (!user.isObject()) {
            throw new ValidacaoException(RAIZ, INVALIDO);
        }
        Campo email = campoObrigatorio(user, "email");
        if (email.presente() && !isEmailValido(email.valor())) {
            throw new ValidacaoException("email", INVALIDO);
        }
        AlteracaoUsuario alteracao = new AlteracaoUsuario(
                email,
                campoObrigatorio(user, "username"),
                campoObrigatorio(user, "password"),
                campoAnulavel(user, "bio"),
                campoAnulavel(user, "image"));
        if (alteracao.isVazia()) {
            throw new ValidacaoException(RAIZ, "must have at least one field");
        }
        return alteracao;
    }

    private static Campo campoObrigatorio(JsonNode user, String nome) {
        if (!user.has(nome)) {
            return Campo.AUSENTE;
        }
        JsonNode valor = user.get(nome);
        if (valor.isNull() || (valor.isString() && valor.stringValue().isBlank())) {
            throw new ValidacaoException(nome, NAO_PODE_SER_VAZIO);
        }
        if (!valor.isString()) {
            throw new ValidacaoException(nome, INVALIDO);
        }
        return Campo.com(valor.stringValue());
    }

    private static Campo campoAnulavel(JsonNode user, String nome) {
        if (!user.has(nome)) {
            return Campo.AUSENTE;
        }
        JsonNode valor = user.get(nome);
        if (valor.isNull()) {
            return Campo.com(null);
        }
        if (!valor.isString()) {
            throw new ValidacaoException(nome, INVALIDO);
        }
        return Campo.com(valor.stringValue());
    }

    private boolean isEmailValido(String email) {
        return validator.validate(new FormatoEmail(email)).isEmpty();
    }

    /** Reaproveita a mesma regra de {@code @Email} usada no cadastro. */
    private record FormatoEmail(@Email String valor) {
    }
}

