    private final AlteracaoUsuarioMapper alteracaoMapper;

    public UsuarioController(UsuarioService usuarioService, TokenService tokenService,
            AlteracaoUsuarioMapper alteracaoMapper) {
        this.usuarioService = usuarioService;
        this.tokenService = tokenService;
        this.alteracaoMapper = alteracaoMapper;
    }

