package com.example.blog.usuario.service;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Optional;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.test.util.ReflectionTestUtils;

import com.example.blog.shared.erro.ConflitoException;
import com.example.blog.shared.erro.CredenciaisInvalidasException;
import com.example.blog.shared.erro.RecursoNaoEncontradoException;
import com.example.blog.shared.erro.TokenInvalidoException;
import com.example.blog.shared.erro.ValidacaoException;
import com.example.blog.shared.seguranca.TokenService;
import com.example.blog.usuario.persistence.Usuario;
import com.example.blog.usuario.persistence.UsuarioRepository;
import com.example.blog.usuario.service.AlteracaoUsuario.Campo;

@ExtendWith(MockitoExtension.class)
class UsuarioServiceTest {

    private static final Instant AGORA = Instant.parse("2026-01-15T10:00:00Z");
    private static final long ID = 7L;

    @Mock
    private UsuarioRepository repository;

    @Mock
    private PasswordEncoder passwordEncoder;

    @Mock
    private TokenService tokenService;

    private UsuarioService service;

    @BeforeEach
    void configurar() {
        service = new UsuarioService(repository, passwordEncoder, tokenService, Clock.fixed(AGORA, ZoneOffset.UTC));
    }

    @Test
    void deveCadastrarGravandoHashEDevolvendoToken() {
        when(passwordEncoder.encode("senha-ficticia")).thenReturn("hash-ficticio");
        when(repository.saveAndFlush(any(Usuario.class))).thenAnswer(chamada -> comId(chamada.getArgument(0), ID));
        when(tokenService.emitir(ID)).thenReturn("token-ficticio");

        UsuarioAutenticado resultado = service.cadastrar("ana", "ana@exemplo.test", "senha-ficticia");

        ArgumentCaptor<Usuario> gravado = ArgumentCaptor.forClass(Usuario.class);
        verify(repository).saveAndFlush(gravado.capture());
        assertThat(gravado.getValue().getSenhaHash()).isEqualTo("hash-ficticio");
        assertThat(gravado.getValue().getCriadoEm()).isEqualTo(AGORA);
        assertThat(resultado).isEqualTo(
                new UsuarioAutenticado("ana@exemplo.test", "token-ficticio", "ana", null, null));
    }

    @Test
    void deveRecusarCadastroComUsernameExistente() {
        when(repository.existsByUsername("ana")).thenReturn(true);

        assertThatThrownBy(() -> service.cadastrar("ana", "ana@exemplo.test", "senha"))
                .isInstanceOfSatisfying(ConflitoException.class, erro -> {
                    assertThat(erro.getChave()).isEqualTo("username");
                    assertThat(erro.getMensagem()).isEqualTo("has already been taken");
                });
        verify(repository, never()).saveAndFlush(any());
    }

    @Test
    void deveRecusarCadastroComEmailExistenteSemDiferenciarMaiusculas() {
        when(repository.existsByEmailIgnoreCase("ANA@exemplo.test")).thenReturn(true);

        assertThatThrownBy(() -> service.cadastrar("ana", "ANA@exemplo.test", "senha"))
                .isInstanceOfSatisfying(ConflitoException.class,
                        erro -> assertThat(erro.getChave()).isEqualTo("email"));
    }

    @Test
    void deveAutenticarComCredenciaisCorretas() {
        Usuario usuario = comId(new Usuario("ana", "ana@exemplo.test", "hash", AGORA), ID);
        when(repository.findByEmailIgnoreCase("ana@exemplo.test")).thenReturn(Optional.of(usuario));
        when(passwordEncoder.matches("senha", "hash")).thenReturn(true);
        when(tokenService.emitir(ID)).thenReturn("token-novo");

        assertThat(service.autenticar("ana@exemplo.test", "senha").token()).isEqualTo("token-novo");
    }

    @Test
    void deveRecusarLoginComEmailInexistente() {
        when(repository.findByEmailIgnoreCase("x@exemplo.test")).thenReturn(Optional.empty());

        assertThatThrownBy(() -> service.autenticar("x@exemplo.test", "senha"))
                .isInstanceOf(CredenciaisInvalidasException.class);
    }

    @Test
    void deveRecusarLoginComSenhaErrada() {
        Usuario usuario = comId(new Usuario("ana", "ana@exemplo.test", "hash", AGORA), ID);
        when(repository.findByEmailIgnoreCase("ana@exemplo.test")).thenReturn(Optional.of(usuario));
        when(passwordEncoder.matches("errada", "hash")).thenReturn(false);

        assertThatThrownBy(() -> service.autenticar("ana@exemplo.test", "errada"))
                .isInstanceOf(CredenciaisInvalidasException.class);
    }

    @Test
    void deveRecusarBuscaDoUsuarioAtualInexistente() {
        when(repository.findById(ID)).thenReturn(Optional.empty());

        assertThatThrownBy(() -> service.buscarAtual(ID, "token")).isInstanceOf(TokenInvalidoException.class);
    }

    @Test
    void deveDevolverUsuarioAtualComOTokenRecebido() {
        Usuario usuario = comId(new Usuario("ana", "ana@exemplo.test", "hash", AGORA), ID);
        when(repository.findById(ID)).thenReturn(Optional.of(usuario));

        assertThat(service.buscarAtual(ID, "token-recebido").token()).isEqualTo("token-recebido");
    }

    @Test
    void deveAtualizarSomenteOsCamposPresentes() {
        Usuario usuario = existente();
        usuario.alterarImage("https://exemplo.test/ana.png", AGORA);
        AlteracaoUsuario alteracao = new AlteracaoUsuario(null, null, null, Campo.com("Nova bio"), null);

        UsuarioAutenticado resultado = service.atualizar(ID, "token", alteracao);

        assertThat(resultado).isEqualTo(new UsuarioAutenticado(
                "ana@exemplo.test", "token", "ana", "Nova bio", "https://exemplo.test/ana.png"));
    }

    @Test
    void deveApagarBioEImageQuandoEnviadosComoNulo() {
        Usuario usuario = existente();
        usuario.alterarBio("Bio", AGORA);
        usuario.alterarImage("https://exemplo.test/ana.png", AGORA);
        AlteracaoUsuario alteracao = new AlteracaoUsuario(null, null, null, Campo.com(null), Campo.com(null));

        UsuarioAutenticado resultado = service.atualizar(ID, "token", alteracao);

        assertThat(resultado.bio()).isNull();
        assertThat(resultado.image()).isNull();
    }

    @Test
    void deveGravarNovoHashAoTrocarASenha() {
        Usuario usuario = existente();
        when(passwordEncoder.encode("nova-senha")).thenReturn("novo-hash");

        service.atualizar(ID, "token", new AlteracaoUsuario(null, null, Campo.com("nova-senha"), null, null));

        assertThat(usuario.getSenhaHash()).isEqualTo("novo-hash");
    }

    @Test
    void deveRecusarUsernameDeOutroUsuarioNaAtualizacao() {
        existente();
        when(repository.existsByUsernameAndIdNot("beto", ID)).thenReturn(true);

        assertThatThrownBy(() -> service.atualizar(ID, "token",
                new AlteracaoUsuario(null, Campo.com("beto"), null, null, null)))
                .isInstanceOfSatisfying(ValidacaoException.class, erro -> {
