package com.example.blog.usuario.web;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import jakarta.validation.Validation;
import jakarta.validation.ValidatorFactory;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

import com.example.blog.shared.erro.ValidacaoException;
import com.example.blog.usuario.service.AlteracaoUsuario;
import com.example.blog.usuario.service.AlteracaoUsuario.Campo;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

class AlteracaoUsuarioMapperTest {

    private static final JsonMapper JSON = JsonMapper.builder().build();
    private static ValidatorFactory fabrica;
    private static AlteracaoUsuarioMapper mapper;

    @BeforeAll
    static void criarMapper() {
        fabrica = Validation.buildDefaultValidatorFactory();
        mapper = new AlteracaoUsuarioMapper(fabrica.getValidator());
    }

    @AfterAll
    static void fecharFabrica() {
        fabrica.close();
    }

    @Test
    void deveMarcarComoAusenteOCampoNaoEnviado() {
        AlteracaoUsuario alteracao = mapper.converter(json("{\"user\":{\"bio\":\"Olá\"}}"));

        assertThat(alteracao.bio()).isEqualTo(Campo.com("Olá"));
        assertThat(alteracao.image()).isEqualTo(Campo.AUSENTE);
        assertThat(alteracao.email()).isEqualTo(Campo.AUSENTE);
    }

    @Test
    void deveMarcarComoPresenteComValorNuloQuandoBioForNull() {
        AlteracaoUsuario alteracao = mapper.converter(json("{\"user\":{\"bio\":null}}"));

        assertThat(alteracao.bio()).isEqualTo(Campo.com(null));
    }

    @Test
    void deveIgnorarCamposDesconhecidos() {
        AlteracaoUsuario alteracao = mapper.converter(json("{\"user\":{\"image\":\"x\",\"outro\":1}}"));

        assertThat(alteracao.image()).isEqualTo(Campo.com("x"));
    }

    @ParameterizedTest
    @CsvSource(delimiter = '|', value = {
        "{\"user\":{\"email\":null}}        | email",
        "{\"user\":{\"email\":\"  \"}}      | email",
        "{\"user\":{\"username\":null}}     | username",
        "{\"user\":{\"username\":\"\"}}     | username",
        "{\"user\":{\"password\":null}}     | password",
        "{\"user\":{\"password\":\" \"}}    | password"
    })
    void deveRecusarCampoObrigatorioNuloOuEmBranco(String corpo, String campo) {
        assertErro(corpo, campo, "can't be blank");
    }

    @Test
    void deveRecusarEmailSemFormato() {
        assertErro("{\"user\":{\"email\":\"nao-e-email\"}}", "email", "is invalid");
    }

    @Test
    void deveRecusarCampoComTipoNaoTexto() {
        assertErro("{\"user\":{\"bio\":10}}", "bio", "is invalid");
    }

    @Test
    void deveRecusarObjetoUserVazio() {
        assertErro("{\"user\":{}}", "user", "must have at least one field");
    }

    @Test
    void deveRecusarObjetoUserSoComCamposDesconhecidos() {
        assertErro("{\"user\":{\"outro\":\"x\"}}", "user", "must have at least one field");
    }

    @Test
    void deveRecusarCorpoSemObjetoUser() {
