package com.example.blog;

import java.security.SecureRandom;
import java.util.Base64;

import org.springframework.test.context.DynamicPropertyRegistry;

/** Gera em tempo de execução o segredo JWT dos testes, para que nenhum segredo fique versionado. */
public final class SegredoJwtDeTeste {

    public static final String PROPRIEDADE = "conduit.jwt.segredo";
    private static final int BYTES = 48;

    private SegredoJwtDeTeste() {
    }

    public static String gerar() {
        byte[] bytes = new byte[BYTES];
        new SecureRandom().nextBytes(bytes);
        return Base64.getEncoder().encodeToString(bytes);
    }

    public static void registrar(DynamicPropertyRegistry registry) {
        String segredo = gerar();
        registry.add(PROPRIEDADE, () -> segredo);
    }
}

