package com.example.blog;

import java.security.SecureRandom;
import java.util.Base64;

import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.springframework.context.annotation.Bean;
import org.springframework.test.context.DynamicPropertyRegistrar;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.testcontainers.utility.DockerImageName;

@TestConfiguration(proxyBeanMethods = false)
public class TestcontainersConfiguration {

    private static final int BYTES_SEGREDO_JWT = 48;

    @Bean
    @ServiceConnection
    PostgreSQLContainer postgresContainer() {
        return new PostgreSQLContainer(DockerImageName.parse("postgres:18.6"));
    }

    /** Gera o segredo do JWT em tempo de execução, para que nenhum segredo de teste fique versionado. */
    @Bean
    DynamicPropertyRegistrar segredoJwtAleatorio() {
        byte[] bytes = new byte[BYTES_SEGREDO_JWT];
        new SecureRandom().nextBytes(bytes);
        String segredo = Base64.getEncoder().encodeToString(bytes);
        return registry -> registry.add("conduit.jwt.segredo", () -> segredo);
    }

}

