package com.example.blog.usuario.web;

import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.context.annotation.Import;
import org.springframework.http.MediaType;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.json.JsonCompareMode;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;

import com.example.blog.SegredoJwtDeTeste;
import com.example.blog.shared.erro.ConflitoException;
import com.example.blog.shared.erro.CredenciaisInvalidasException;
import com.example.blog.shared.seguranca.SegurancaConfig;
import com.example.blog.shared.seguranca.TokenService;
import com.example.blog.usuario.service.UsuarioAutenticado;
import com.example.blog.usuario.service.UsuarioService;

@WebMvcTest(UsuarioController.class)
@Import({SegurancaConfig.class, TokenService.class, AlteracaoUsuarioMapper.class})
class UsuarioControllerCadastroLoginTest {

    private static final UsuarioAutenticado ANA =
            new UsuarioAutenticado("ana@exemplo.test", "token-ficticio", "ana", null, null);

    @Autowired
    private MockMvc mockMvc;

    @MockitoBean
    private UsuarioService usuarioService;

    @DynamicPropertySource
    static void propriedades(DynamicPropertyRegistry registry) {
        SegredoJwtDeTeste.registrar(registry);
    }

    @Test
    void deveCadastrarERetornar201ComUsuario() throws Exception {
        when(usuarioService.cadastrar("ana", "ana@exemplo.test", "senha")).thenReturn(ANA);

        cadastrar("{\"user\":{\"username\":\"ana\",\"email\":\"ana@exemplo.test\",\"password\":\"senha\"}}")
                .andExpect(status().isCreated())
                .andExpect(content().contentType("application/json"))
                .andExpect(content().json("""
                        {"user":{"email":"ana@exemplo.test","token":"token-ficticio","username":"ana",
                        "bio":null,"image":null}}
                        """, JsonCompareMode.STRICT));
    }

    @Test
    void deveRecusarCadastroComCamposAusentesOuEmBranco() throws Exception {
        cadastrar("{\"user\":{\"username\":\"  \"}}")
                .andExpect(status().isUnprocessableContent())
                .andExpect(content().json("""
                        {"errors":{"username":["can't be blank"],"email":["can't be blank"],
                        "password":["can't be blank"]}}
                        """, JsonCompareMode.STRICT));
    }

    @Test
    void deveRecusarCadastroComEmailSemFormato() throws Exception {
        cadastrar("{\"user\":{\"username\":\"ana\",\"email\":\"nao-e-email\",\"password\":\"senha\"}}")
                .andExpect(status().isUnprocessableContent())
                .andExpect(content().json("{\"errors\":{\"email\":[\"is invalid\"]}}", JsonCompareMode.STRICT));
    }

    @Test
    void deveRecusarJsonMalformado() throws Exception {
        cadastrar("{\"user\":")
                .andExpect(status().isUnprocessableContent())
                .andExpect(jsonPath("$.errors.body[0]").value("is invalid"));
    }

    @Test
    void deveRecusarCorpoSemObjetoUser() throws Exception {
        cadastrar("{}")
                .andExpect(status().isUnprocessableContent())
                .andExpect(content().json("{\"errors\":{\"user\":[\"can't be blank\"]}}", JsonCompareMode.STRICT));
    }

    @Test
    void deveRecusarCadastroDuplicadoCom409() throws Exception {
        when(usuarioService.cadastrar(anyString(), anyString(), anyString()))
                .thenThrow(new ConflitoException("username", "has already been taken"));

        cadastrar("{\"user\":{\"username\":\"ana\",\"email\":\"ana@exemplo.test\",\"password\":\"senha\"}}")
                .andExpect(status().isConflict())
                .andExpect(content().json(
                        "{\"errors\":{\"username\":[\"has already been taken\"]}}", JsonCompareMode.STRICT));
    }

    @Test
    void deveEntrarERetornar200() throws Exception {
        when(usuarioService.autenticar("ana@exemplo.test", "senha")).thenReturn(ANA);

        entrar("{\"user\":{\"email\":\"ana@exemplo.test\",\"password\":\"senha\"}}")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.user.token").value("token-ficticio"));
    }

    @Test
    void deveRecusarLoginComCamposEmBranco() throws Exception {
        entrar("{\"user\":{\"email\":\"\"}}")
                .andExpect(status().isUnprocessableContent())
                .andExpect(content().json("""
                        {"errors":{"email":["can't be blank"],"password":["can't be blank"]}}
                        """, JsonCompareMode.STRICT));
    }

    @Test
    void deveRecusarLoginComCredenciaisInvalidasCom401() throws Exception {
        when(usuarioService.autenticar(anyString(), anyString())).thenThrow(new CredenciaisInvalidasException());

        entrar("{\"user\":{\"email\":\"ana@exemplo.test\",\"password\":\"errada\"}}")
                .andExpect(status().isUnauthorized())
                .andExpect(content().json("{\"errors\":{\"credentials\":[\"invalid\"]}}", JsonCompareMode.STRICT));
    }

    private ResultActions cadastrar(String corpo) throws Exception {
        return mockMvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(corpo));
    }

    private ResultActions entrar(String corpo) throws Exception {
        return mockMvc.perform(post("/api/users/login").contentType(MediaType.APPLICATION_JSON).content(corpo));
    }
}

