package com.example.blog.usuario;

import static com.example.blog.ApiTestSupport.CONTENT_TYPE_ESPERADO;
import static com.example.blog.ApiTestSupport.SENHA;
import static com.example.blog.ApiTestSupport.autorizacao;
import static com.example.blog.ApiTestSupport.corpoCadastro;
import static com.example.blog.ApiTestSupport.corpoLogin;
import static com.example.blog.ApiTestSupport.nomeUnico;

import java.time.Duration;
import java.time.Instant;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.SpringBootTest.WebEnvironment;
import org.springframework.boot.web.server.test.LocalServerPort;
import org.springframework.context.annotation.Import;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.security.oauth2.jose.jws.MacAlgorithm;
import org.springframework.security.oauth2.jwt.JwsHeader;
import org.springframework.security.oauth2.jwt.JwtClaimsSet;
import org.springframework.security.oauth2.jwt.JwtEncoder;
import org.springframework.security.oauth2.jwt.JwtEncoderParameters;
import org.springframework.test.web.servlet.client.RestTestClient;

import com.example.blog.ApiTestSupport;
import com.example.blog.TestcontainersConfiguration;

@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
@Import(TestcontainersConfiguration.class)
class UsuarioApiIT {

    @LocalServerPort
    private int porta;

    @Autowired
    private JwtEncoder jwtEncoder;

    private ApiTestSupport api;
    private RestTestClient cliente;

    @BeforeEach
    void configurar() {
        api = new ApiTestSupport(porta);
        cliente = api.cliente();
    }

    @Test
    void deveCadastrarCom201() {
        String username = nomeUnico("ana");

        cliente.post().uri("/api/users")
                .contentType(MediaType.APPLICATION_JSON)
                .body(corpoCadastro(username, username + "@exemplo.test", SENHA))
                .exchange()
                .expectStatus().isCreated()
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody()
                .jsonPath("$.user.username").isEqualTo(username)
                .jsonPath("$.user.email").isEqualTo(username + "@exemplo.test")
                .jsonPath("$.user.token").isNotEmpty()
                .jsonPath("$.user.bio").isEmpty()
                .jsonPath("$.user.image").isEmpty()
                .jsonPath("$.user.password").doesNotExist();
    }

    @Test
    void deveRecusarUsernameRepetidoCom409() {
        String username = nomeUnico("ana");
        api.cadastrar(username);

        cliente.post().uri("/api/users")
                .contentType(MediaType.APPLICATION_JSON)
                .body(corpoCadastro(username, nomeUnico("outro") + "@exemplo.test", SENHA))
                .exchange()
                .expectStatus().isEqualTo(409)
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody().json("{\"errors\":{\"username\":[\"has already been taken\"]}}");
    }

    @Test
    void deveRecusarEmailQueDifereSoEmMaiusculasCom409() {
        String username = nomeUnico("ana");
        api.cadastrar(username);

        cliente.post().uri("/api/users")
                .contentType(MediaType.APPLICATION_JSON)
                .body(corpoCadastro(nomeUnico("outro"), username.toUpperCase() + "@EXEMPLO.TEST", SENHA))
                .exchange()
                .expectStatus().isEqualTo(409)
                .expectBody().json("{\"errors\":{\"email\":[\"has already been taken\"]}}");
    }

    @Test
    void deveEntrarComCredenciaisCorretas() {
        String username = nomeUnico("ana");
        api.cadastrar(username);

        cliente.post().uri("/api/users/login")
                .contentType(MediaType.APPLICATION_JSON)
                .body(corpoLogin(username.toUpperCase() + "@exemplo.test", SENHA))
                .exchange()
                .expectStatus().isOk()
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody()
                .jsonPath("$.user.username").isEqualTo(username)
                .jsonPath("$.user.token").isNotEmpty();
    }

    @Test
    void deveRecusarLoginComSenhaErradaCom401() {
        String username = nomeUnico("ana");
        api.cadastrar(username);

        cliente.post().uri("/api/users/login")
                .contentType(MediaType.APPLICATION_JSON)
                .body(corpoLogin(username + "@exemplo.test", "senha-errada"))
                .exchange()
                .expectStatus().isUnauthorized()
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody().json("{\"errors\":{\"credentials\":[\"invalid\"]}}");
    }

    @Test
    void deveRecusarCadastroComEmailVazioCom422() {
        cliente.post().uri("/api/users")
                .contentType(MediaType.APPLICATION_JSON)
                .body(corpoCadastro(nomeUnico("ana"), "", SENHA))
                .exchange()
                .expectStatus().isEqualTo(422)
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody().json("{\"errors\":{\"email\":[\"can't be blank\"]}}");
    }

    @Test
    void deveDevolverUsuarioAtualComOMesmoToken() {
        String username = nomeUnico("ana");
        String token = api.cadastrar(username);

        cliente.get().uri("/api/user")
                .header(HttpHeaders.AUTHORIZATION, autorizacao(token))
                .exchange()
                .expectStatus().isOk()
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody()
                .jsonPath("$.user.username").isEqualTo(username)
                .jsonPath("$.user.token").isEqualTo(token);
    }

    @Test
    void deveRefletirBioEImageAtualizadosEApagarImageComNull() {
        String token = api.cadastrar(nomeUnico("ana"));

        atualizar(token, "{\"user\":{\"bio\":\"Olá\",\"image\":\"https://exemplo.test/a.png\"}}")
                .expectStatus().isOk();
        cliente.get().uri("/api/user")
                .header(HttpHeaders.AUTHORIZATION, autorizacao(token))
                .exchange()
                .expectBody()
                .jsonPath("$.user.bio").isEqualTo("Olá")
                .jsonPath("$.user.image").isEqualTo("https://exemplo.test/a.png");

        atualizar(token, "{\"user\":{\"image\":null}}")
                .expectStatus().isOk()
                .expectBody()
                .jsonPath("$.user.bio").isEqualTo("Olá")
                .jsonPath("$.user.image").isEmpty();
    }

    @Test
    void deveAceitarSomenteANovaSenhaAposTroca() {
        String username = nomeUnico("ana");
        String token = api.cadastrar(username);

        atualizar(token, "{\"user\":{\"password\":\"nova-senha-ficticia\"}}").expectStatus().isOk();

        entrar(username + "@exemplo.test", SENHA).expectStatus().isUnauthorized();
        entrar(username + "@exemplo.test", "nova-senha-ficticia").expectStatus().isOk();
    }

    @Test
    void deveRecusarEmailDeOutroUsuarioNaAtualizacaoCom422() {
        String outro = nomeUnico("beto");
        api.cadastrar(outro);
        String token = api.cadastrar(nomeUnico("ana"));

        atualizar(token, "{\"user\":{\"email\":\"" + outro + "@exemplo.test\"}}")
                .expectStatus().isEqualTo(422)
                .expectBody().json("{\"errors\":{\"email\":[\"has already been taken\"]}}");
    }

    @Test
    void deveRecusarRequisicaoSemTokenCom401IsMissing() {
        cliente.get().uri("/api/user")
                .exchange()
                .expectStatus().isUnauthorized()
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody().json("{\"errors\":{\"token\":[\"is missing\"]}}");
    }

    @Test
    void deveRecusarTokenExpiradoCom401() {
        Instant emitidoEm = Instant.now().minus(Duration.ofDays(2));
        String expirado = assinar(JwtClaimsSet.builder()
                .subject("1").issuer("conduit").issuedAt(emitidoEm).expiresAt(emitidoEm.plus(Duration.ofHours(24)))
                .build());

        cliente.get().uri("/api/user")
                .header(HttpHeaders.AUTHORIZATION, autorizacao(expirado))
                .exchange()
                .expectStatus().isUnauthorized()
                .expectBody().json("{\"errors\":{\"token\":[\"is invalid\"]}}");
    }

    @Test
    void deveRecusarTokenComAssinaturaInvalidaCom401() {
        String token = api.cadastrar(nomeUnico("ana"));
        String semAssinatura = token.substring(0, token.lastIndexOf('.') + 1);

        cliente.get().uri("/api/user")
                .header(HttpHeaders.AUTHORIZATION, autorizacao(semAssinatura + "assinaturainvalida"))
                .exchange()
                .expectStatus().isUnauthorized()
                .expectBody().json("{\"errors\":{\"token\":[\"is invalid\"]}}");
    }

    @Test
    void deveRecusarTokenDeUsuarioInexistenteCom401() {
        Instant agora = Instant.now();
        String token = assinar(JwtClaimsSet.builder()
                .subject(Long.toString(Long.MAX_VALUE)).issuer("conduit")
                .issuedAt(agora).expiresAt(agora.plus(Duration.ofHours(1)))
                .build());

        cliente.get().uri("/api/user")
                .header(HttpHeaders.AUTHORIZATION, autorizacao(token))
                .exchange()
                .expectStatus().isUnauthorized()
                .expectBody().json("{\"errors\":{\"token\":[\"is invalid\"]}}");
    }

    private RestTestClient.ResponseSpec atualizar(String token, String corpo) {
        return cliente.put().uri("/api/user")
                .header(HttpHeaders.AUTHORIZATION, autorizacao(token))
                .contentType(MediaType.APPLICATION_JSON)
                .body(corpo)
                .exchange();
    }

    private RestTestClient.ResponseSpec entrar(String email, String senha) {
        return cliente.post().uri("/api/users/login")
                .contentType(MediaType.APPLICATION_JSON)
                .body(corpoLogin(email, senha))
                .exchange();
    }

    private String assinar(JwtClaimsSet claims) {
        JwsHeader cabecalho = JwsHeader.with(MacAlgorithm.HS256).build();
        return jwtEncoder.encode(JwtEncoderParameters.from(cabecalho, claims)).getTokenValue();
    }
}

