package com.example.blog;

import java.util.UUID;

import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.client.RestTestClient;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/** Apoio aos testes de API: cliente HTTP real e criação de usuários fictícios únicos. */
public final class ApiTestSupport {

    public static final String CONTENT_TYPE_ESPERADO = "application/json;charset=UTF-8";
    public static final String SENHA = "senha-ficticia-1";

    private static final JsonMapper JSON = JsonMapper.builder().build();

    private final RestTestClient cliente;

    public ApiTestSupport(int porta) {
        this.cliente = RestTestClient.bindToServer().baseUrl("http://localhost:" + porta).build();
    }

    public RestTestClient cliente() {
        return cliente;
    }

    /** Nome de usuário fictício e único para isolar os testes entre si. */
    public static String nomeUnico(String prefixo) {
        return prefixo + "-" + UUID.randomUUID().toString().substring(0, 8);
    }

    public static String corpoCadastro(String username, String email, String senha) {
        return """
                {"user":{"username":"%s","email":"%s","password":"%s"}}""".formatted(username, email, senha);
    }

    public static String corpoLogin(String email, String senha) {
        return """
                {"user":{"email":"%s","password":"%s"}}""".formatted(email, senha);
    }

    /** Cadastra um usuário fictício e devolve o token emitido. */
    public String cadastrar(String username) {
        String corpo = cliente.post().uri("/api/users")
                .contentType(MediaType.APPLICATION_JSON)
                .body(corpoCadastro(username, username + "@exemplo.test", SENHA))
                .exchange()
                .expectStatus().isCreated()
                .expectBody(String.class).returnResult().getResponseBody();
        return json(corpo).get("user").get("token").stringValue();
    }

    public static String autorizacao(String token) {
        return "Token " + token;
    }

    public static String cabecalhoAutorizacao() {
        return HttpHeaders.AUTHORIZATION;
    }

    public static JsonNode json(String texto) {
        return JSON.readTree(texto);
    }
}

