package com.example.blog.perfil.web;

import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.context.annotation.Import;
import org.springframework.http.HttpHeaders;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.json.JsonCompareMode;
import org.springframework.test.web.servlet.MockMvc;

import com.example.blog.SegredoJwtDeTeste;
import com.example.blog.perfil.service.Perfil;
import com.example.blog.perfil.service.PerfilService;
import com.example.blog.shared.erro.RecursoNaoEncontradoException;
import com.example.blog.shared.erro.ValidacaoException;
import com.example.blog.shared.seguranca.SegurancaConfig;
import com.example.blog.shared.seguranca.TokenService;

@WebMvcTest(PerfilController.class)
@Import({SegurancaConfig.class, TokenService.class})
class PerfilControllerTest {

    private static final long ID = 1L;

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private TokenService tokenService;

    @MockitoBean
    private PerfilService perfilService;

    @DynamicPropertySource
    static void propriedades(DynamicPropertyRegistry registry) {
        SegredoJwtDeTeste.registrar(registry);
    }

    @Test
    void deveDevolverPerfilParaAnonimoComNulosSerializados() throws Exception {
        when(perfilService.buscar("ana")).thenReturn(new Perfil("ana", null, null, false));

        mockMvc.perform(get("/api/profiles/ana"))
                .andExpect(status().isOk())
                .andExpect(content().json("""
                        {"profile":{"username":"ana","bio":null,"image":null,"following":false}}
                        """, JsonCompareMode.STRICT));
    }

    @Test
    void deveDevolverPerfilComoUsuarioAutenticado() throws Exception {
        when(perfilService.buscarComo(ID, "ana")).thenReturn(new Perfil("ana", null, null, true));

        mockMvc.perform(get("/api/profiles/ana").header(HttpHeaders.AUTHORIZATION, tokenValido()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.profile.following").value(true));
    }

    @Test
    void deveRecusarTokenInvalidoMesmoComAutenticacaoOpcional() throws Exception {
        mockMvc.perform(get("/api/profiles/ana").header(HttpHeaders.AUTHORIZATION, "Token invalido"))
                .andExpect(status().isUnauthorized())
                .andExpect(content().json("{\"errors\":{\"token\":[\"is invalid\"]}}", JsonCompareMode.STRICT));
        verifyNoInteractions(perfilService);
    }

    @Test
    void deveResponder404QuandoPerfilNaoExiste() throws Exception {
        when(perfilService.buscar("ninguem")).thenThrow(new RecursoNaoEncontradoException("profile", "not found"));

        mockMvc.perform(get("/api/profiles/ninguem"))
                .andExpect(status().isNotFound())
                .andExpect(content().json("{\"errors\":{\"profile\":[\"not found\"]}}", JsonCompareMode.STRICT));
    }

    @Test
    void deveExigirTokenParaSeguir() throws Exception {
        mockMvc.perform(post("/api/profiles/ana/follow"))
                .andExpect(status().isUnauthorized())
                .andExpect(content().json("{\"errors\":{\"token\":[\"is missing\"]}}", JsonCompareMode.STRICT));
    }

    @Test
    void deveExigirTokenParaDeixarDeSeguir() throws Exception {
        mockMvc.perform(delete("/api/profiles/ana/follow"))
                .andExpect(status().isUnauthorized())
                .andExpect(content().json("{\"errors\":{\"token\":[\"is missing\"]}}", JsonCompareMode.STRICT));
    }

    @Test
    void deveSeguirComUsuarioAutenticado() throws Exception {
        when(perfilService.seguir(ID, "ana")).thenReturn(new Perfil("ana", null, null, true));

        mockMvc.perform(post("/api/profiles/ana/follow").header(HttpHeaders.AUTHORIZATION, tokenValido()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.profile.following").value(true));
    }

    @Test
    void deveDeixarDeSeguirComUsuarioAutenticado() throws Exception {
        when(perfilService.deixarDeSeguir(ID, "ana")).thenReturn(new Perfil("ana", null, null, false));

        mockMvc.perform(delete("/api/profiles/ana/follow").header(HttpHeaders.AUTHORIZATION, tokenValido()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.profile.following").value(false));
    }

    @Test
    void deveResponder422AoSeguirASiMesmo() throws Exception {
        when(perfilService.seguir(ID, "ana")).thenThrow(new ValidacaoException("profile", "cannot follow yourself"));

        mockMvc.perform(post("/api/profiles/ana/follow").header(HttpHeaders.AUTHORIZATION, tokenValido()))
                .andExpect(status().isUnprocessableContent())
                .andExpect(content().json(
                        "{\"errors\":{\"profile\":[\"cannot follow yourself\"]}}", JsonCompareMode.STRICT));
    }

    private String tokenValido() {
        return "Token " + tokenService.emitir(ID);
    }
}

