@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
@Import(TestcontainersConfiguration.class)
class PerfilApiIT {

    @LocalServerPort
    private int porta;

    private ApiTestSupport api;
    private RestTestClient cliente;

    @BeforeEach
    void configurar() {
        api = new ApiTestSupport(porta);
        cliente = api.cliente();
    }

    @Test
    void deveDevolverPerfilAnonimoComFollowingFalso() {
        String ana = nomeUnico("ana");
        api.cadastrar(ana);

        cliente.get().uri("/api/profiles/{username}", ana)
                .exchange()
                .expectStatus().isOk()
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody().json("""
                        {"profile":{"username":"%s","bio":null,"image":null,"following":false}}
                        """.formatted(ana));
    }

    @Test
    void deveRecusarTokenInvalidoCom401() {
        String ana = nomeUnico("ana");
        api.cadastrar(ana);

        cliente.get().uri("/api/profiles/{username}", ana)
                .header(HttpHeaders.AUTHORIZATION, "Token invalido")
                .exchange()
                .expectStatus().isUnauthorized()
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody().json("{\"errors\":{\"token\":[\"is invalid\"]}}");
    }

    @Test
    void deveResponder404ParaPerfilInexistente() {
        cliente.get().uri("/api/profiles/{username}", nomeUnico("ninguem"))
                .exchange()
                .expectStatus().isNotFound()
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody().json("{\"errors\":{\"profile\":[\"not found\"]}}");
    }

    @Test
    void deveSeguirEDeixarDeSeguirDeFormaIdempotente() {
        String ana = nomeUnico("ana");
        api.cadastrar(ana);
        String tokenBeto = api.cadastrar(nomeUnico("beto"));

        seguir(tokenBeto, ana).expectStatus().isOk().expectBody().jsonPath("$.profile.following").isEqualTo(true);
        seguir(tokenBeto, ana).expectStatus().isOk().expectBody().jsonPath("$.profile.following").isEqualTo(true);

        cliente.get().uri("/api/profiles/{username}", ana)
                .header(HttpHeaders.AUTHORIZATION, autorizacao(tokenBeto))
                .exchange()
                .expectStatus().isOk()
                .expectBody().jsonPath("$.profile.following").isEqualTo(true);

        deixarDeSeguir(tokenBeto, ana)
                .expectStatus().isOk()
                .expectHeader().valueEquals(HttpHeaders.CONTENT_TYPE, CONTENT_TYPE_ESPERADO)
                .expectBody().jsonPath("$.profile.following").isEqualTo(false);
        deixarDeSeguir(tokenBeto, ana).expectStatus().isOk().expectBody().jsonPath("$.profile.following").isEqualTo(false);

        cliente.get().uri("/api/profiles/{username}", ana)
                .header(HttpHeaders.AUTHORIZATION, autorizacao(tokenBeto))
                .exchange()
                .expectBody().jsonPath("$.profile.following").isEqualTo(false);
    }

    @Test
    void deveRecusarSeguirASiMesmoCom422() {
        String ana = nomeUnico("ana");
        String tokenAna = api.cadastrar(ana);

        seguir(tokenAna, ana)
                .expectStatus().isEqualTo(422)
                .expectBody().json("{\"errors\":{\"profile\":[\"cannot follow yourself\"]}}");
    }

    @Test
    void deveResponder404AoSeguirAlvoInexistente() {
        String token = api.cadastrar(nomeUnico("ana"));

        seguir(token, nomeUnico("ninguem")).expectStatus().isNotFound();
        deixarDeSeguir(token, nomeUnico("ninguem")).expectStatus().isNotFound();
    }

    @Test
    void deveExigirTokenParaSeguirEDeixarDeSeguir() {
        String ana = nomeUnico("ana");
        api.cadastrar(ana);

        cliente.post().uri("/api/profiles/{username}/follow", ana)
                .exchange()
                .expectStatus().isUnauthorized()
                .expectBody().json("{\"errors\":{\"token\":[\"is missing\"]}}");
        cliente.delete().uri("/api/profiles/{username}/follow", ana)
                .exchange()
                .expectStatus().isUnauthorized()
                .expectBody().json("{\"errors\":{\"token\":[\"is missing\"]}}");
    }

    private RestTestClient.ResponseSpec seguir(String token, String username) {
        return cliente.post().uri("/api/profiles/{username}/follow", username)
                .header(HttpHeaders.AUTHORIZATION, autorizacao(token))
                .exchange();
    }

    private RestTestClient.ResponseSpec deixarDeSeguir(String token, String username) {
        return cliente.delete().uri("/api/profiles/{username}/follow", username)
                .header(HttpHeaders.AUTHORIZATION, autorizacao(token))
                .exchange();
    }
}

