    ResponseEntity<ErroResponse> tratarConflito(ConflitoException excecao) {
        return responder(HttpStatus.CONFLICT, excecao);
    }

    @ExceptionHandler(ValidacaoException.class)
    ResponseEntity<ErroResponse> tratarValidacaoDeNegocio(ValidacaoException excecao) {
        return responder(HttpStatus.UNPROCESSABLE_CONTENT, excecao);
    }

    @ExceptionHandler(CredenciaisInvalidasException.class)
    ResponseEntity<ErroResponse> tratarCredenciaisInvalidas(CredenciaisInvalidasException excecao) {
        return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(ErroResponse.de("credentials", "invalid"));
    }

    @ExceptionHandler(TokenInvalidoException.class)
    ResponseEntity<ErroResponse> tratarTokenInvalido(TokenInvalidoException excecao) {
        return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(ErroResponse.de("token", "is invalid"));
    }

    @ExceptionHandler(Exception.class)
    ResponseEntity<ErroResponse> tratarInesperado(Exception excecao) {
        if (excecao instanceof ErrorResponse erroDoFramework) {
            return tratarErroDoFramework(erroDoFramework);
        }
        log.error("Erro inesperado ao processar a requisição", excecao);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(ErroResponse.de("server", "unexpected error"));
    }

    private static ResponseEntity<ErroResponse> responder(HttpStatus status, ErroDeNegocioException excecao) {
        return ResponseEntity.status(status).body(ErroResponse.de(excecao.getChave(), excecao.getMensagem()));
    }

    /** Exceções do próprio Spring MVC (rota inexistente, método não suportado etc.) mantêm o status original. */
    private static ResponseEntity<ErroResponse> tratarErroDoFramework(ErrorResponse erro) {
        HttpStatusCode status = erro.getStatusCode();
        HttpStatus conhecido = HttpStatus.resolve(status.value());
        String mensagem = conhecido == null ? "is invalid" : conhecido.getReasonPhrase().toLowerCase(Locale.ROOT);
        return ResponseEntity.status(status).body(ErroResponse.de("request", mensagem));
    }

    private static String removerPrefixoRaiz(String campo) {
        return campo.startsWith(PREFIXO_RAIZ) ? campo.substring(PREFIXO_RAIZ.length()) : campo;
    }

    /** Campo vazio torna as demais mensagens do mesmo campo irrelevantes (ex.: formato de e-mail). */
    private static List<String> priorizarCampoVazio(Set<String> mensagens) {
        if (mensagens.contains(NAO_PODE_SER_VAZIO)) {
            return List.of(NAO_PODE_SER_VAZIO);
        }
        return List.copyOf(mensagens);
    }
}

